scripts.script:
const isFirst = actor.getFlag('xjzl-system', 'neigong_lianhualuo_first');
if (isFirst) {
    args.output.damage += 20;
    args.output.bonusDesc.push('莲花落首刀 +20');
}

const isFirst = actor.getFlag('xjzl-system', 'neigong_lianhualuo_first');
// 只有攻击命中才消耗，治疗/Buff不消耗
if (isFirst && args.actionType === 'attack' && args.isHit) {
    await actor.setFlag('xjzl-system', 'neigong_lianhualuo_first', false);
    ui.notifications.info(`${actor.name} 的莲花落首刀效果已触发。`);
}

if (args.move.damageType === 'waigong') {
    const neixi = S.stats.neixi.total || 0;
    const bonus = Math.floor(neixi * 0.2);
    if (bonus > 0) {
        args.output.damage += bonus;
        args.output.bonusDesc.push(`混天劲 +${bonus}`);
    }
}

if (args.move.damageType === 'waigong') {
    const neixi = S.stats.neixi.total || 0;
    const bonus = Math.floor(neixi * 0.3);
    if (bonus > 0) {
        args.output.damage += bonus;
        args.output.bonusDesc.push(`混天劲 +${bonus}`);
    }
}

if (args.actionType !== 'attack' || !args.isHit) return;
const targetId = args.target.id;
const flagKey = `neigong_yuyang_hits_${targetId}`;
let hits = actor.getFlag('xjzl-system', flagKey) || 0;
hits += 1;

if (hits >= 3) {
    // 检查内力
    if (S.resources.mp.value >= 5) {
        // 消耗内力
        await actor.changeResources({'system.resources.mp.value': S.resources.mp.value - 5}, { cause: "moveCost", source: "move", sourceActor: actor, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
        // 重置计数
        hits = 0;

        // 1. 击倒 (Prone)
        await game.xjzl.api.effects.toggleStatus(args.target, 'prone', true);

        // 2. 流失伤害 (0.5 * 力量)
        const dmg = Math.floor(S.stats.liliang.total * 0.5);
        await args.target.applyDamage({
            amount: dmg,
            type: 'liushi',
            attacker: actor,
            isHit: true
        });
        ui.notifications.info(`${actor.name} 玉阳诀发动！消耗5点内力击倒了目标并造成流失。`);
    } else {
        ui.notifications.warn('玉阳诀触发，但内力不足！');
        hits = 2; // 保持在2，下次有蓝就能触发
    }
}
await actor.setFlag('xjzl-system', flagKey, hits);

if (args.actionType !== 'attack' || !args.isHit) return;
const targetId = args.target.id;
const flagKey = `neigong_yuyang_hits_${targetId}`;
let hits = actor.getFlag('xjzl-system', flagKey) || 0;
hits += 1;

if (hits >= 3) {
    if (S.resources.mp.value >= 5) {
        await actor.changeResources({'system.resources.mp.value': S.resources.mp.value - 5}, { cause: "moveCost", source: "move", sourceActor: actor, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
        hits = 0;
        await game.xjzl.api.effects.toggleStatus(args.target, 'prone', true);

        const dmg = Math.floor(S.stats.liliang.total * 1.0);
        await args.target.applyDamage({
            amount: dmg,
            type: 'liushi',
            attacker: actor,
            isHit: true
        });
        ui.notifications.info(`${actor.name} 玉阳诀发动！消耗5点内力击倒了目标并造成流失。`);
    } else {
        ui.notifications.warn('玉阳诀触发，但内力不足！');
        hits = 2;
    }
}
await actor.setFlag('xjzl-system', flagKey, hits);

if (!args.attacker) return;
if (!thisEffect.origin) return; // 寻找特效的源头内功模板
const originItem = await fromUuid(thisEffect.origin);
if (!originItem) return;
const jiuzuiTpl = originItem.effects.getName('酒醉');
if (jiuzuiTpl) {
    const effData = jiuzuiTpl.toObject();
    delete effData._id;
    effData.origin = thisEffect.origin;
    await game.xjzl.api.effects.addEffect(args.attacker, effData);
    ui.notifications.info(`${args.attacker.name} 攻击带有醉雨的目标，沾染上了极其浓烈的酒气！`);
}

if (!args.attacker) return;
if (!thisEffect.origin) return; // 寻找特效的源头内功模板
const originItem = await fromUuid(thisEffect.origin);
if (!originItem) return;
const jiuzuiTpl = originItem.effects.getName('酒醉');
if (jiuzuiTpl) {
    const effData = jiuzuiTpl.toObject();
    delete effData._id;
    effData.origin = thisEffect.origin;
    await game.xjzl.api.effects.addEffect(args.attacker, effData);
    ui.notifications.info(`${args.attacker.name} 攻击带有醉雨的目标，沾染上了极其浓烈的酒气！`);
}

if (!args.attacker) return;
if (!thisEffect.origin) return; // 寻找特效的源头内功模板
const originItem = await fromUuid(thisEffect.origin);
if (!originItem) return;
const jiuzuiTpl = originItem.effects.getName('酒醉');
if (jiuzuiTpl) {
    const effData = jiuzuiTpl.toObject();
    delete effData._id;
    effData.origin = thisEffect.origin;
    await game.xjzl.api.effects.addEffect(args.attacker, effData);
    ui.notifications.info(`${args.attacker.name} 攻击带有醉雨的目标，沾染上了极其浓烈的酒气！`);
}

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const stacks = thisEffect.getFlag('xjzl-system', 'stacks') || 1;
if (stacks > 0) {
    const result = await foundry.applications.api.DialogV2.prompt({
        window: { title: '消耗酒醉', icon: 'fas fa-wine-bottle' },
        content: `<div style="padding:5px;"><p>当前拥有 <b>${stacks}</b> 层【酒醉】。</p><p>出招前，每消耗一层暴击骰 -1。</p><hr><div style="display:flex; align-items:center; gap:10px;"><label>消耗层数 (0-${stacks}):</label><input type="number" name="consume" value="0" min="0" max="${stacks}" autofocus style="width:60px; text-align:center;"></div></div>`,
        ok: {
            label: '确认',
            icon: 'fas fa-check',
            callback: (evt, btn) => {
                const fd = new FormData(btn.form);
                return parseInt(fd.get('consume')) || 0;
            }
        },
        rejectClose: false
    });
    if (result > 0) {
        let actual = Math.min(result, stacks);
        await game.xjzl.api.effects.removeEffect(actor, 'jiuzui', actual);
        args.flags.critThresholdMod += actual;
        args.flags.damageResult.breakdown += `\n+ 酒醉: 暴击阈值 -${actual}`;
        ui.notifications.info(`消耗 ${actual} 层酒醉，暴击阈值 -${actual}！`);
    }
}
